 function renderCharacter(){let all=Object.entries(s.deeds).sort((a,b)=>b[1]-a[1]);el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location">THE WAYFARER · SELF-KNOWLEDGE</div><span class="day">Level ${s.level}</span></div><section class="panel view-panel"><div class="eyebrow">The person you are becoming</div><h2 style="margin-top:6px">${esc(s.name)}</h2><p>${esc(s.ancestry)} ${esc(s.background)} · ${s.vocation?`<b style="color:var(--gold2)">${s.vocation}</b>`:'<span style="color:var(--green)">Unclassed — your deeds will reveal your calling.</span>'}</p><div class="stat-grid" style="margin-top:15px">${Object.entries(s.stats).map(([k,v])=>`<div class="stat"><div class="stat-label">${k}</div><div class="stat-value">${v} <small>${modText(mod(v))}</small></div></div>`).join('')}</div><div class="section-heading"><h2>Practiced skills</h2><span class="quiet">Proficiency +2</span></div><div class="chips">${s.skills.map(x=>`<span class="chip">${x} ${modText(skillBonus(x))}</span>`).join('')}</div><div class="section-heading"><h2>Deeds that define you</h2><span class="quiet">Your choices become your calling</span></div>${all.length?all.map(([k,v])=>`<div class="list-row"><div class="item-icon">${({social:'♡',explore:'⌖',faith:'☼',craft:'⚒',lore:'✧',combat:'⚔'})[k]||'◈'}</div><div class="list-copy"><div class="list-title" style="text-transform:capitalize">${k}</div><div class="list-desc">${v} meaningful ${v===1?'deed':'deeds'}</div></div><div class="quiet">${'✦'.repeat(Math.min(5,v))}</div></div>`).join(''):'<div class="quiet">Your story has only just begun.</div>'}${s.vocation?`<div class="section-heading"><h2>Calling: ${s.vocation}</h2><span class="quiet">Subclass unlocks at level 3</span></div><p>${s.subclass?`You follow the ${esc(s.subclass)} path.`:'At level 3, choose a path that feels true to your story.'}</p>`:''}</section><section class="panel view-panel"><div class="eyebrow">The Greenmarch</div><h2 style="margin-top:6px">Your origins</h2><p>${esc(