 function renderQuests(){el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location">THE JOURNAL · THREADS OF FATE</div><span class="day">${s.quests.filter(q=>q.done).length} completed</span></div><section class="panel view-panel"><div class="eyebrow">Your story has many threads</div><h2 style="margin-top:6px">Quest journal</h2><p>Not every meaningful journey begins with a quest. These are simply the promises you have chosen to keep.</p>${s.quests.map(q=>`<div class="list-row"><div class="item-icon">${q.done?'✓':'⚑'}</div><div class="list-copy"><div class="list-title">${esc(q.name)} ${q.done?'<span class="chip">Complete</span>':''}</div><div class="list-desc">${esc(q.desc)}</div><div class="meter" style="max-width:260px"><span style="width:${q.done?100:q.progress/q.total*100}%"></span></div></div><div class="quiet">${q.done?'Done':`${q.progress}/${q.total}`}</div></div>`).join('')}</section><section class="panel view-panel"><div class="eyebrow">An open world</div><h2 style="margin-top:6px">No quest required</h2><p>Make a living, seek the old gods, trade favors, join a guild, or follow a hunch. Your calling is shaped by the things you choose to do.</p><button class="action-btn" data-goto="chronicle">Return to the world →</button></section>`;el('#mainContent').onclick=e=>{if(e.target.closest('[data-goto]')){s.tab='chronicle';render()}}}
