+function mod(v){return Math.floor((v-10)/2)}function modText(n){return n>=0?'+'+n:String(n)}function pointCost(v){return ({8:0,9:1,10:2,11:3,12:4,13:5,14:7,15:9})[v]??99}function pointsSpent(o){return Object.values(o).reduce((a,v)=>a+pointCost(v),0)}
