 function updateShell(){el('#sideName').textContent=s.name;el('#sideOrigin').textContent=`${s.ancestry} · ${s.background}`;el('#sideLevel').textContent=`Level ${s.level} · ${s.vocation||'Unclassed'}`;el('#sideXp').textContent=`${s.xp} / ${xpNeed()} XP`;el('#sideXpBar').style.width=`${Math.min(100,s.xp/xpNeed()*100)}%`;el('#levelTiny').textContent=`Level ${s.level+1}`;el('#headerDay').textContent=`✧ ${dayName(s.day)}`;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===s.tab));el('#questBadge').textContent=s.quests.filter(q=>!q.done).length||'✓';}
