 function renderCreator(){el('#rightbar').innerHTML='';el('#mainContent').innerHTML='<div style="height:45vh;min-height:300px;display:grid;place-items:center;text-align:center"><div><div class="sigil" style="margin:auto;width:58px;height:58px;font-size:28px">✦</div><div class="eyebrow" style="margin-top:20px">A world waiting to be changed</div><h1 style="font:600 34px var(--serif);margin:8px 0">Every legend begins<br>with a choice.</h1><p style="color:var(--muted);font:14px var(--serif);max-width:400px;line-height:1.6">There are no destinies here—only the life you choose to lead.</p><button class="primary" onclick="openCreator()" style="margin-top:14px">Begin your chronicle →</button></div></div>';}
