+function itemMeta(i){return `${Number(i.weight||0)} wt · ${i.durability??'—'}/${i.maxDurability??i.durability??'—'} durability · Requires ${esc(i.requirement||'None')}`}function rollRarity(){let n=Math.random()*100;return n<1?'Legendary':n<6?'Epic':n<17?'Rare':n<40?'Uncommon':'Common'}function makeItem(category,merchantId='world',slot=0){let pool=itemPools[category]||itemPools.herbs,base=pool[Math.floor(Math.random()*pool.length)],rarity=rollRarity(),mult={Common:1,Uncommon:1.45,Rare:2.2,Epic:3.5,Legendary:6}[rarity],prefix={Common:'',Uncommon:'Fine ',Rare:'Runed ',Epic:'Elder ',Legendary:'Mythic '}[rarity],dur=Math.max(1,Math.round(base[5]*({Common:1,Uncommon:1.15,Rare:1.35,Epic:1.6,Legendary:2}[rarity]))),req=base[6];if(rarity==='Rare'||rarity==='Epic'||rarity==='Legendary')req=(['STR','DEX','CON','INT','WIS','CHA'][Math.floor(Math.random()*6)])+' '+({Rare:11,Epic:13,Legendary:15}[rarity]);return{id:`${merchantId}-${slot}-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,name:prefix+base[0],icon:base[1],desc:base[2],type:base[3],category,rarity,weight:base[4],durability:dur,maxDurability:dur,requirement:req,value:Math.max(1,Math.round(base[7]*mult)),qty:1,equipped:false}}function meetsRequirement(i){if(!i.requirement||i.requirement==='None')return true;let m=i.requirement.match(/(STR|DEX|CON|INT|WIS|CHA)\s*(\d+)/);return !m||(s.stats[m[1]]||0)>=Number(m[2])}function wearGear(tag){let types=tag==='combat'?['weapon','armor']:['craft','explore'].includes(tag)?['tool']:['lore','faith'].includes(tag)?['charm']:[];let worn=[];for(let i of s.inventory){if(i.equipped&&types.includes(i.type)&&Number.isFinite(i.durability)&&i.durability>0){i.durability--;if(i.durability===0){i.equipped=false;worn.push(`${i.name} broke`)}else worn.push(`${i.name} ${i.durability}/${i.maxDurability} durability`)}}return worn}function renderSceneArt(){return `<div class="scene-art"><div class="moon"></div><div class="ridge back"></div><div class="ridge"></div><div class="pine p1"></div><div class="pine p2"></div><div class="pine p3"></div><div class="town"><div class="house small"></div><div class="house"></div><div class="house small"></div></div><div class="fog"></div></div>`}
 function renderChronicle(){let sc=scenes[s.location%scenes.length];let choices=sc.choices.map(([title,desc,icon,tag],i)=>`<button class="choice" data-choice="${i}"><span class="choice-top"><span class="choice-title">${esc(title)}</span><span class="choice-glyph">${icon}</span></span><span class="choice-desc">${esc(desc)}</span></button>`).join('');el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location"><b>✧ ${esc(sc.region)}</b></div><span class="day">${dayName(s.day)}</span></div><section class="scene">${renderSceneArt()}<div class="scene-tag">${esc(sc.tag)}</div><div class="scene-caption"><h1>${esc(sc.name)}</h1><p>${esc(sc.region.split(' · ')[0])} — The Greenmarch</p></div></section><section class="panel narrative"><p>${esc(s.lastNarration||sc.intro)}<br><span class="italic">${s.turn===0?'The world waits to see what you make of this moment.':'Your story is yours to write. What will you do next?'}</span></p></section><div class="section-heading"><h2>What do you do?</h2><span class="quiet">Choose a path, or write your own</span></div><div class="choices" id="choices">${choices}</div><form class="freeform" id="freeform"><input id="freeText" maxlength="180" autocomplete="off" placeholder="Try anything… talk, explore, make, pray"><button class="send">Act →</button></form><div class="roll-banner ${s.rollText?'show':''}" id="rollBanner"><span class="die">⚄</span><span id="rollText">${esc(s.rollText||'')}</span></div><div class="panel view-panel" style="margin-top:14px"><div class="right-heading"><h3>Recent moments</h3><span class="quiet">Your chronicle</span></div>${s.log.length?s.log.slice(0,3).map(x=>`<div class="feed-entry"><small>${esc(x.kind)} · day ${x.day}</small>${esc(x.text)}</div>`).join(''):'<div class="quiet">The page is still blank.</div>'}</div>`;
 el('#choices').onclick=e=>{let b=e.target.closest('[data-choice]');if(b)act(sc.choices[+b.dataset.choice][0],sc.choices[+b.dataset.choice][3])};el('#freeform').onsubmit=e=>{e.preventDefault();let text=el('#freeText').value.trim();if(text){actFree(text);el('#freeText').value=''}};}
