 function act(title,tag){let skillsBy={social:'Persuasion',explore:'Survival',faith:'Insight',craft:'Craft',lore:'Arcana',combat:'Athletics'};let skill=skillsBy[tag]||'Insight';let die=1+Math.floor(Math.random()*20),bonus=skillBonus(skill),dc=11,total=die+bonus,success=total>=dc;s.turn++;s.choiceCount++;s.day+=Math.random()<.25?1:0;s.deeds[tag]=(s.deeds[tag]||0)+1;let current=scenes[s.location%scenes.length];let outcomes={social:success?'Your approach earns a more candid answer. A detail that had seemed incidental now sounds important.':'The response stays guarded. A pause and a careful change of subject tell their own story.',explore:success?'You follow the clue beyond the familiar paths. A curious little relic waits where the mist parts.':'The wild keeps its secret for now. Still, you notice a trail leading toward the Lanternwood.',faith:success?'The candle-flame steadies. For one breath, the shrine feels less like a ruin and more like a promise.':'The flame gutters, then burns on. Even unanswered prayers leave a mark.',craft:success?'A little care makes a real difference. The villagers notice—and someone presses a few coins into your hand.':'Your effort is appreciated, though the repair will take more work. A useful lesson, at least.',lore:success?'The old marks resolve into a name: Nym, the Unmoored Star. A fragment of amberglass warms in your palm.':'The marks resist easy reading. You copy them down; knowledge can wait.',combat:success?'You meet the danger with calm and clear purpose. The way ahead opens.':'You keep your footing and avoid the worst of it. The road is still yours.'};let text=`${title} — ${outcomes[tag]||'The moment unfolds in a way only you could have set in motion.'}`;let worn=wearGear(tag);if(worn.length)text+=` Equipment: ${worn.join(', ')}.`;if(success&&tag==='explore'&&!s.inventory.some(i=>i.id==='wildflower'))s.inventory.push({id:'wildflower',name:'Moonlit wildflower',icon:'✿',desc:'A pale bloom that only opens after dusk.',type:'herb',value:5,qty:1});if(success&&tag==='craft'){s.gold+=3;text+=' (+3 silver marks)'}if(tag==='social'){s.relations.Mara=Math.min(5,(s.relations.Mara||0)+(success?1:0));if(s.quests[0]&&!s.quests[0].done)s.quests[0].progress=Math.min(3,s.quests[0].progress+1)}if(tag==='lore'||tag==='explore'){if(s.quests[0]&&!s.quests[0].done)s.quests[0].progress=Math.min(3,s.quests[0].progress+1)}if(s.quests[0]&&s.quests[0].progress>=s.quests[0].total&&!s.quests[0].done){s.quests[0].done=true;s.gold+=s.quests[0].reward;text+=` Quest complete: “${s.quests[0].name}.” (+${s.quests[0].reward} silver marks)`;gainXP(40)}gainXP(success?25:12);if(s.turn%3===0){s.location=(s.location+1)%scenes.length;s.day++}s.lastNarration=text;pushLog(tag,text);s.rollText=`${skill} check: d20 ${die} ${bonus>=0?'+':''}${bonus} = ${total} vs DC ${dc} · ${success?'Success':'A complication'}. ${text}`;earned();render();}
function actFree(text){let lower=text.toLowerCase(),tag=/pray|shrine|god|offering|worship/.test(lower)?'faith':/craft|make|repair|build|cook|gather|forage|brew/.test(lower)?'craft':/talk|ask|persuad|convince|greet|tell|listen|friend|flirt/.test(lower)?'social':/read|rune|study|research|remember|history/.test(lower)?'lore':/fight|attack|strike|defend|duel|hunt/.test(lower)?'combat':'explore';let title=text.length>44?text.slice(0,41)+'…':text;act(title,tag);let response=s.lastNarration.split(' — ').slice(1).join(' — ');s.lastNarration=`You decide to ${text}. ${response}`;save();render()}
function renderRight(){let open=s.quests.filter(q=>!q.done);el('#rightbar').innerHTML=`<section class="panel right-card"><div class="right-heading"><h3>In your thoughts</h3><button class="link-btn" data-tab="quests">All quests →</button></div>${open.length?open.slice(0,2).map(q=>`<div class="quest"><div class="quest-name">${esc(q.name)}</div><div class="quest-sub">${esc(q.desc)}</div><div class="meter"><span style="width:${q.progress/q.total*100}%"></span></div></div>`).join(''):'<div class="quiet">No open quests. Follow your curiosity.</div>'}</section><section class="panel right-card"><div class="right-heading"><h3>Familiar faces</h3><span class="quiet">Social web</span></div><div class="npc-row"><div class="avatar">M</div><div class="npc-copy"><div class="npc-name">Mara Vell</div><div class="npc-note">Ferrymaster · ${s.relations.Mara>1?'Trusting':s.relations.Mara?'Warming':'Acquaintance'}</div></div><span class="heart">${'♥'.repeat(Math.max(1,s.relations.Mara+1))}</span></div><div class="npc-row"><div class="avatar">R</div><div class="npc-copy"><div class="npc-name">Rowan Thistle</div><div class="npc-note">Shrine novice · ${s.relations.Rowan?'Grateful':'New acquaintance'}</div></div><span class="heart">♥</span></div></section><section class="panel right-card"><div class="right-heading"><h3>Your bearings</h3><button class="link-btn" data-tab="character">Details →</button></div><div class="stat-grid">${Object.entries(s.stats).map(([k,v])=>`<div class="stat"><div class="stat-label">${k}</div><div class="stat-value">${v} <small>${modText(mod(v))}</small></div></div>`).join('')}</div><div class="tiny-row" style="margin-top:12px"><span>Silver marks</span><b style="color:var(--gold2)">◈ ${s.gold}</b></div></section><section class="panel right-card"><div class="eyebrow">A whisper at the edge</div><p style="font:13px/1.5 var(--serif);color:#c5cabb;margin:8px 0 0">“The bell remembers a name the living have forgotten.”</p></section>`;el('#rightbar').onclick=e=>{let b=e.target.closest('[data-tab]');if(b){s.tab=b.dataset.tab;render()}}}
function renderCharacter(){let all=Object.entries(s.deeds).sort((a,b)=>b[1]-a[1]);el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location">THE WAYFARER · SELF-KNOWLEDGE</div><span class="day">Level ${s.level}</span></div><section class="panel view-panel"><div class="eyebrow">The person you are becoming</div><h2 style="margin-top:6px">${esc(s.name)}</h2><p>${esc(s.ancestry)} ${esc(s.background)} · ${s.vocation?`<b style="color:var(--gold2)

### function renderInventory( 
 function renderInventory(){el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location">THE WAYFARER · WHAT YOU CARRY</div><span class="day">◈ ${s.gold} silver marks</span></div><section class="panel view-panel"><div class="eyebrow">Pack & provisions</div><h2 style="margin-top:6px">Inventory</h2><p>Merchants keep their own hours and stock. Buy only where your travels take you; carried goods can be sold here.</p>${s.inventory.length?s.inventory.map(i=>{let canEquip=['weapon','armor','tool','charm'].includes(i.type),action=i.type==='food'||i.type==='herb'?'use':i.equipped?'unequip':'equip';return `<div class="list-row"><div class="item-icon">${esc(i.icon||'◈')}</div><div class="list-copy"><div class="list-title">${esc(i.name)} ${i.equipped?'<span class="chip">Equipped</span>':''}</div><div class="list-desc">${esc(i.desc)} · x${i.qty}</div><div class="item-meta"><span class="quality">${esc(i.rarity||'Common')}</span> · ${Number(i.weight||0)} wt · ${i.durability??'—'}/${i.maxDurability??i.durability??'—'} durability · Requires ${esc(i.requirement||'None')}</div></div>${i.type==='food'||i.type==='herb'||canEquip?`<button class="action-btn" data-item="${esc(i.id)}" data-action="${action}" ${!meetsRequirement(i)||(action==='equip'&&i.durability===0)?'disabled title="Requirement not met or item is broken"':''}>${action==='use'?'Use':action==='unequip'?'Unequip':'Equip'}</button>`:''}<button class="action-btn" data-sell="${esc(i.id)}">Sell · ◈${Math.max(1,Math.floor((i.value||1)*.7))}</button></div>`}).join(''):'<div class="quiet">Your pack is empty.</div>'}</section>`;el('#mainContent').onclick=e=>{let b=e.target.closest('[data-item]');if(b){let i=s.inventory.find(x=>x.id===b.dataset.item);if(!i)return;if(!meetsRequirement(i)){toast(`Requires ${i.requirement}.`)}else if(b.dataset.action==='use'){if((i.type==='herb'||i.type==='food')&&i.qty>0){if(i.qty>1)i.qty--;else s.inventory=s.inventory.filter(x=>x!==i);gainXP(5);toast(`${i.name} used.`)}}else if(i.durability===0&&!i.equipped){toast(`${i.name} is broken and cannot be equipped.`)}else{i.equipped=!i.equipped;toast(i.equipped?`${i.name} equipped.`:`${i.name} put away.`)}render();return}let sell=e.target.closest('[data-sell]');if(sell){let i=s.inventory.find(x=>x.id===sell.dataset.sell);if(i){s.gold+=Math.max(1,Math.floor((i.value||1)*.7));if(i.qty>1)i.qty--;else s.inventory=s.inventory.filter(x=>x!==i);toast(`Sold ${i.name}.`);render()}}}}
function merchantOpen(m){return m.places.includes(s.location)}

### function renderMerchants( 
 function renderMerchants(){let here=merchants.filter(merchantOpen),active=merchants.find(m=>m.id===s.activeMerchant&&merchantOpen(m));let current=scenes[s.location%scenes.length];el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location">THE GREENMARCH · LOCAL TRADE</div><span class="day">${esc(current.name)} · ◈ ${s.gold}</span></div><section class="panel view-panel"><div class="eyebrow">Trade follows the road</div><h2 style="margin-top:6px">Merchants</h2><p>No universal market waits in your pack. Shops have distinct goods, finite stock, and are open only while you are nearby.</p><div class="merchant-grid">${merchants.map(m=>{let open=merchantOpen(m),stock=s.shopStocks[m.id]?.items||[];return `<article class="merchant-card ${open?'':'disabled-note'}"><div class="eyebrow">${m.icon} ${esc(m.kind)}</div><h3>${esc(m.name)}</h3><p>${esc(m.desc)}</p><div class="quiet">${open?'Open here now':`Found near ${m.places.map(i=>scenes[i].name).join(' / ')}`} · ${stock.length} goods in stock</div>${open?`<button class="action-btn" data-visit="${m.id}">${active?.id===m.id?'Viewing stock':'Visit shop'} →</button>`:'<span class="quiet">Not in this place</span>'}</article>`}).join('')}</div></section>${active?(()=>{let stock=shopStock(active);return `<section class="panel view-panel"><div class="right-heading"><div><div class="eyebrow">${esc(active.kind)} · ${esc(current.name)}</div><h2 style="margin-top:5px">${esc(active.name)}</h2></div><span class="quiet">Restocks every few days</span></div>${stock.items.length?stock.items.map((i,n)=>{let price=i.value;return `<div class="list-row"><div class="item-icon">${esc(i.icon)}</div><div class="list-copy"><div class="list-title">${esc(i.name)} <span class="quality">${esc(i.rarity)}</span></div><div class="list-desc">${esc(i.desc)}</div><div class="item-meta">${itemMeta(i)}</div></div><button class="action-btn" data-buy-slot="${n}" ${s.gold<price?'disabled':''}>Buy · ◈${price}</button></div>`}).join(''):'<div class="quiet">This shelf is empty until the next restock.</div>'}</section>`})():''}`;el('#mainContent').onclick=e=>{let v=e.target.closest('[data-visit]');if(v){let m=merchants.find(x=>x.id===v.dataset.visit);if(!m||!merchantOpen(m))return;s.activeMerchant=m.id;shopStock(m);render();return}let b=e.target.closest('[data-buy-slot]');if(b&&active){let stock=shopStock(active),n=Number(b.dataset.buySlot),i=stock.items[n];if(!i)return;if(!merchantOpen(active)){toast('The shop is no longer nearby.');s.activeMerchant=null;render();return}if(s.gold<i.value){toast('Not enough silver marks.');return}s.gold-=i.value;s.inventory.push({...i,id:`${i.id}-owned-${s.turn}`,qty:1,equipped:false});stock.items.splice(n,1);toast(`${i.name} bought from ${active.name}.`);pushLog('trade',`You bought ${i.name} at ${active.name}.`);render()}}}

### function renderPeople( 
 function renderPeople(){let present=(s.npcs||[]).filter(n=>n.place===s.location),traveling=(s.npcs||[]).filter(n=>n.recruited);let current=scenes[s.location%scenes.length];el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location">THE GREENMARCH · PEOPLE & PROMISES</div><span class="day">${esc(current.name)}</span></div><section class="panel view-panel"><div class="eyebrow">A small world of lasting ties</div><h2 style="margin-top:6px">People</h2><p>Faces are distinct, and conversations leave memories. Trust may grow or fray over time; an invitation is never an obligation.</p>${present.length?present.map(n=>`<article class="npc-card"><div class="npc-card-head"><div class="avatar">${esc(n.name[0])}</div><div class="list-copy"><div class="list-title">${esc(n.name)} ${n.recruited?'<span class="chip">Traveling with you</span>':''}</div><div class="list-desc">${esc(n.role)} · ${n.trust>=3?'Close ally':n.trust>0?'Warming':n.trust<0?'Wary':'Acquaintance'} · Trust ${n.trust||0}</div></div></div><div class="npc-trait">${esc(n.tell)}</div><div class="npc-actions"><button class="action-btn" data-talk="${n.id}">Speak</button><button class="action-btn" data-share="${n.id}" ${s.gold<2?'disabled':''}>Share a meal · ◈2</button>${n.recruited?'<span class="chip">On the road</span>':`<button class="action-btn" data-invite="${n.id}">Invite to travel</button>`}</div>${n.memory?.length?`<div class="item-meta">Lasting memory: ${esc(n.memory[0].text)} · day ${n.memory[0].day}</div>`:''}</article>`).join(''):'<div class="quiet">No one you know is here just now. Familiar people remain in the journal of your travels.</div>'}</section><section class="panel view-panel"><div class="eyebrow">Your companions</div><h2 style="margin-top:6px">On the road</h2>${traveling.length?traveling.map(n=>`<div class="list-row"><div class="item-icon">♧</div><div class="list-copy"><div class="list-title">${esc(n.name)}</div><div class="list-desc">${esc(n.role)} · Trust ${n.trust}</div></div><button class="action-btn" data-part="${n.id}">Part ways</button></div>`).join(''):'<p class="quiet">No one has joined your travels.</p>'}</section>`;el('#mainContent').onclick=e=>{let b=e.target.closest('[data-talk],[data-share],[data-invite],[data-part]');if(!b)return;let n=s.npcs.find(x=>x.id===(b.dataset.talk||b.dataset.share||b.dataset.invite||b.dataset.part));if(!n)return;if(b.dataset.talk){let skill=skillBonus('Persuasion'),roll=1+Math.floor(Math.random()*20),ok=roll+skill>=11,words=ok?`${n.name} answers in kind; the conversation settles into a little more trust.`:`${n.name} listens, though some part of the subject remains guarded.`;remember(n,ok?'A thoughtful conversation':'A guarded conversation',ok?1:0);s.deeds.social=(s.deeds.social||0)+1;s.lastNarration=words;toast(words);gainXP(ok?8:4)}if(b.dataset.share){if(s.gold<2){toast('Not enough silver marks.');return}s.gold-=2;remember(n,'Shared a meal and an unhurried hour',1);s.lastNarration=`You share food with ${n.name}. The meal is simple, and the time is freely given.`;gainXP(8);toast('The meal is remembered.')}if(b.dataset.invite){if(n.recruited){toast(`${n.name} already travels with you.`);return}if(!n.willing){remember(n,'Declined an invitation; the forge and village still need them',1);s.lastNarration=`${n.name} appreciates the invitation, but will not leave the life and people entrusted to them.`;toast(`${n.name} will not leave their place.`)}else if((n.trust||0)<2){remember(n,'An invitation came before trust was ready',0);s.lastNarration=`${n.name} considers the invitation, then asks for more time. The answer is not yet a promise.`;toast(`${n.name} is not ready to travel.`)}else{n.recruited=true;s.joined.push(`companion:${n.id}`);remember(n,'Agreed to travel together',1);s.lastNarration=`${n.name} agrees to share the road. They remain their own person, with their own reasons for coming.`;toast(`${n.name} joined your travels.`);gainXP(20)}}if(b.dataset.part){n.recruited=false;s.joined=s.joined.filter(x=>x!==`companion:${n.id}`);remember(n,'Parted ways with the wayfarer',-1);s.lastNarration=`You and ${n.name} part without erasing what came before.`;toast(`${n.name} left the road.`)}render()}}
 const guilds=[{id:'wayfarers',name:'Wayfarers’ Compact',icon:'⌖',type:'Public',desc:'A loose fellowship of guides, couriers, and seekers. No road is too small to matter.'},{id:'lantern',name:'The Lantern Covenant',icon:'☼',type:'Public',desc:'Keepers of shrines and gentle guardians of the old faiths.'},{id:'verdant',name:'Verdant Circle',icon:'✿',type:'Public',desc:'Herbalists and wardens tending the uneasy border between village and wild.'},{id:'ash',name:'The Ashen Ledger',icon:'◈',type:'Secret',desc:'A quiet society that trades in forgotten names and forbidden histories.'},{id:'unmoored',name:'The Unmoored',icon:'✧',type:'Secret',desc:'Those who have slipped the notice of kings, gods, and fate itself.'}];
function renderWorld(){let joined=s.joined||[];el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location">THE GREENMARCH · REALMS & POWERS</div><span class="day">An interconnected world</span></div><section class="panel view-panel"><div class="eyebrow">The powers that shape the realm</div><h2 style="margin-top:6px">Governments & gods</h2><p>The Greenmarch is held by the March Council, a compact of village stewards under Duchess Elowen’s distant rule. The crown’s writ thins with every mile from the capital.</p>${gods.map((g,i)=>`<div class="list-row"><div class="item-icon">${['♨','✧','✿','◉'][i]}</div><div class="list-copy"><div class="list-title">${g[0]}</div><div class="list-desc">${g[1]}</div></div>${s.offering===g[0]?'<span class="chip">Known to you</span>':`<button class="action-btn" data-offer="${i}">Offer a prayer</button>`}</div>`).join('')}</section><section class="panel view-panel"><div class="eyebrow">Find your people</div><h2 style="margin-top:6px">Guilds & hidden doors</h2><p>Public guilds welcome curious hands. Secret societies reveal themsel

### function renderWorld( 
 function renderWorld(){let joined=s.joined||[];el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location">THE GREENMARCH · REALMS & POWERS</div><span class="day">An interconnected world</span></div><section class="panel view-panel"><div class="eyebrow">The powers that shape the realm</div><h2 style="margin-top:6px">Governments & gods</h2><p>The Greenmarch is held by the March Council, a compact of village stewards under Duchess Elowen’s distant rule. The crown’s writ thins with every mile from the capital.</p>${gods.map((g,i)=>`<div class="list-row"><div class="item-icon">${['♨','✧','✿','◉'][i]}</div><div class="list-copy"><div class="list-title">${g[0]}</div><div class="list-desc">${g[1]}</div></div>${s.offering===g[0]?'<span class="chip">Known to you</span>':`<button class="action-btn" data-offer="${i}">Offer a prayer</button>`}</div>`).join('')}</section><section class="panel view-panel"><div class="eyebrow">Find your people</div><h2 style="margin-top:6px">Guilds & hidden doors</h2><p>Public guilds welcome curious hands. Secret societies reveal themselves only to those who notice the signs—or earn someone’s trust.</p>${guilds.map(g=>{let known=g.type==='Public'||s.deeds.lore>=2||s.deeds.social>=3;let member=joined.includes(g.id);return `<div class="list-row"><div class="item-icon">${known?g.icon:'?'}</div><div class="list-copy"><div class="list-title">${known?g.name:'An unmarked circle'} <span class="chip">${known?g.type:'Secret'}</span></div><div class="list-desc">${known?g.desc:'You notice a repeating symbol among the old records. More may be revealed as you explore.'}</div></div>${known?(member?'<span class="chip">Member</span>':`<button class="action-btn" data-guild="${g.id}">Join</button>`):'<span class="quiet">Undiscovered</span>'}</div>`}).join('')}</section><section class="panel view-panel"><div class="eyebrow">A living economy</div><h2 style="margin-top:6px">The market remembers</h2><p>Local prices shift with scarcity, season, and trust. Trade with the villagers from your <button class="link-btn" data-goto="inventory">inventory</button>. A generous deed may open a better bargain than a full purse.</p></section>`;el('#mainContent').onclick=e=>{let b=e.target.closest('[data-guild]');if(b){let g=guilds.find(x=>x.id===b.dataset.guild);s.joined.push(g.id);pushLog('faction',`You joined ${g.name}.`);gainXP(15);toast(`Joined ${g.name}.`);render()}let o=e.target.closest('[data-offer]');if(o){let g=gods[+o.dataset.offer][0];s.offering=g;s.deeds.faith=(s.deeds.faith||0)+1;s.gold=Math.max(0,s.gold-1);s.relations.Rowan=Math.min(5,(s.relations.Rowan||0)+1);gainXP(12);pushLog('faith',`You left a silver mark for ${g}.`);toast('Your offering is remembered.');render()}if(e.target.closest('[data-goto]')){s.tab='inventory';render()}}}
function showSubclass(){if(s.subclass||!s.vocation)return;let paths={Warden:['Green Knight','Shieldbearer'],Arcanist:['Starcaller','Runescribe'],Envoy:['Voice of the People','Silver Tongue'],Wayfarer:['Pathfinder','Beast Friend'],Artificer:['Tinker-Savant','Master Alchemist'],Luminary:['Hearth Saint','Veil-Seer'],Sage:['Keeper of Names','Loreweaver']};let opts=paths[s.vocation]||['The Open Hand','The Far-Seer'];el('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-kicker">Level 3 · A defining choice</div><h1>Which path calls to you?</h1><p class="modal-intro">Your calling is ${esc(s.vocation)}. You have lived enough to choose what it means.</p><div class="options">${opts.map((x,i)=>`<button class="option" data-subclass="${esc(x)}">${esc(x)}<small>${i?'A subtler, stranger path':'A steady, time-honored path'}</small></button>`).join('')}</div><div class="modal-actions"><span>This choice will shape the chapters ahead.</span></div></div></div>`;el('#modalRoot').onclick=e=>{let b=e.target.closest('[data-subclass]');if(b){s.subclass=b.dataset.subclass;pushLog('milestone',`At level 3, you chose the ${s.subclass} path.`);el('#modalRoot').innerHTML='';render();toast(`Path chosen: ${s.subclass}`)}}}
function init(){document.body.addEventListener('click',e=>{let b=e.target.closest('[data-tab]');if(b){s.tab=b.dataset.tab;render()}});el('#resetBtn').onclick=()=>{if(confirm('Begin a new chronicle? Your current story will be erased.')){s=initial();save();render()}};render()}
init();
})();
</script></body></html>

